import json

# Safe parse — returns None instead of crashing
def safe_parse(text):
    try:
        return json.loads(text)
    except json.JSONDecodeError:
        return None

# Validate required fields — returns list of error strings
def check_required(data, required):
    return [f"missing: {f}" for f in required if f not in data]

