import json

def extract_and_validate(llm_content, required):
    try:
        data = json.loads(llm_content)
    except json.JSONDecodeError:
        return None, ["invalid JSON"]
    errors = [f"missing: {f}" for f in required if f not in data]
    return data, errors

content = '{"name": "Alice", "role": "engineer"}'
data, errors = extract_and_validate(content, ["name", "role", "team"])
print(data)    # {'name': 'Alice', 'role': 'engineer'}
print(errors)  # ['missing: team']
